conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>

#include <mma.h>
#include <cute/tensor.hpp>

using namespace cute;
using namespace nvcuda;

constexpr int kThreads = 256;
constexpr int kInChannels = 3;
constexpr int kOutChannels = 32;
constexpr int kKernel = 3;
constexpr int kGemmM = 256;
constexpr int kGemmN = 32;
constexpr int kGemmK = 32;
constexpr int kKActual = kInChannels * kKernel * kKernel;
constexpr int kWarpTile = 16;
constexpr int kWarpMTiles = 4;
constexpr int kWarps = kThreads / 32;
static_assert(kKActual == 27, "Unexpected reduction size");
static_assert(kGemmK >= kKActual, "K tile must cover the padded reduction");
static_assert(kGemmN == kOutChannels, "N tile must cover all output channels");
static_assert(kGemmM % kWarpTile == 0, "M tile must be divisible by warp tile");
static_assert(kGemmN % kWarpTile == 0, "N tile must be divisible by warp tile");
static_assert(kWarps * kWarpMTiles == (kGemmM / kWarpTile) * (kGemmN / kWarpTile),
              "Four 16x16 warp tiles per warp");
__global__ void __launch_bounds__(kThreads, 1)
conv2d_bf16_k3_cin3_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    int height_in,
    int width_in,
    int height_out,
    int width_out,
    int64_t x_batch_stride,
    int64_t y_batch_stride)
{
  const int tid = threadIdx.x;
  const int batch = blockIdx.y;
  const int m0 = blockIdx.x * kGemmM;
  const int64_t pixels_per_image = (int64_t)height_out * width_out;
  const int64_t x_c_stride = (int64_t)height_in * width_in;
  const int64_t y_c_stride = (int64_t)height_out * width_out;
  const __nv_bfloat16* __restrict__ x_batch = X + (int64_t)batch * x_batch_stride;
  __nv_bfloat16* __restrict__ y_batch = Y + (int64_t)batch * y_batch_stride;
  // Implicit-GEMM tiles: A is MxK stored col-major, B is KxN stored col-major.
  // K = 27 is zero-padded to 32 so one 16x16x16 BF16 tensor-core step finishes the reduction.
  // Stage C per-warp instead of as one 256x32 fp32 tile: the per-warp
  // 16x16 staging buffers (8KB total) are aliased over the A/B operand
  // buffers, which are dead after the MMA phase. Static shared memory
  // drops from ~33KB to 18KB, doubling the smem-limited occupancy.
  constexpr int kSmemABytes = kGemmK * kGemmM * (int)sizeof(__nv_bfloat16);
  constexpr int kSmemBBytes = kGemmN * kGemmK * (int)sizeof(__nv_bfloat16);
  constexpr int kSmemCWarpFloats = kWarpTile * kWarpTile;
  constexpr int kSmemCBytes = kWarps * kSmemCWarpFloats * (int)sizeof(float);
  static_assert(kSmemCBytes <= kSmemABytes + kSmemBBytes,
                "Per-warp C staging must fit inside the aliased A/B storage");
  constexpr int kSmemBytes = kSmemABytes + kSmemBBytes;
  __shared__ __align__(16) unsigned char smem_raw[kSmemBytes];
  __nv_bfloat16* smem_a = reinterpret_cast<__nv_bfloat16*>(smem_raw);
  __nv_bfloat16* smem_b = reinterpret_cast<__nv_bfloat16*>(smem_raw + kSmemABytes);
  float* smem_c = reinterpret_cast<float*>(smem_raw);
  const __nv_bfloat16 bf16_zero = __float2bfloat16_rn(0.0f);
  // Load A by kernel-width groups: for each (ci,kh), one thread loads the
  // four consecutive input taps needed by kw=0..2 for a pair of output
  // pixels and reuses the overlapped taps instead of reloading them per k.
  constexpr int kRowPairs = kGemmM / 2;
  constexpr int kAGroups = kInChannels * kKernel * kRowPairs;
  for (int idx = tid; idx < kAGroups; idx += kThreads) {
    const int ci = idx / (kKernel * kRowPairs);
    const int rem_ci = idx - ci * (kKernel * kRowPairs);
    const int kh = rem_ci / kRowPairs;
    const int rp = rem_ci - kh * kRowPairs;
    const int r = rp * 2;
    const int kbase = (ci * kKernel + kh) * kKernel;
    __nv_bfloat16 f0 = bf16_zero, f1 = bf16_zero, f2 = bf16_zero;
    __nv_bfloat16 s0 = bf16_zero, s1 = bf16_zero, s2 = bf16_zero;
    const int64_t global_m = (int64_t)m0 + r;
    if (global_m < pixels_per_image) {
      const int out_h = (int)(global_m / width_out);
      const int out_w = (int)(global_m - (int64_t)out_h * width_out);
      const __nv_bfloat16* src0 = x_batch + (int64_t)ci * x_c_stride +
                                  (int64_t)(out_h + kh) * width_in + out_w;
      const bool has_second = (global_m + 1 < pixels_per_image);
      const bool same_row = has_second && (out_w + 1 < width_out);
      if (same_row) {
        __nv_bfloat16 i0, i1, i2, i3;
        if ((reinterpret_cast<uintptr_t>(src0) & 0x3) == 0) {
          const __nv_bfloat162 q0 =
              *reinterpret_cast<const __nv_bfloat162*>(src0);
          const __nv_bfloat162 q1 =
              *reinterpret_cast<const __nv_bfloat162*>(src0 + 2);
          i0 = q0.x;
          i1 = q0.y;
          i2 = q1.x;
          i3 = q1.y;
        } else {
          i0 = src0[0];
          i1 = src0[1];
          i2 = src0[2];
          i3 = src0[3];
        }
        f0 = i0;
        f1 = i1;
        f2 = i2;
        s0 = i1;
        s1 = i2;
        s2 = i3;
      } else {
        f0 = src0[0];
        f1 = src0[1];
        f2 = src0[2];
        if (has_second) {
          const __nv_bfloat16* srcw = x_batch + (int64_t)ci * x_c_stride +
                                      (int64_t)(out_h + 1 + kh) * width_in;
          s0 = srcw[0];
          s1 = srcw[1];
          s2 = srcw[2];
        }
      }
    }
    __nv_bfloat162 spair;
    spair.x = f0;
    spair.y = s0;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + (kbase + 0) * kGemmM + r) = spair;
    spair.x = f1;
    spair.y = s1;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + (kbase + 1) * kGemmM + r) = spair;
    spair.x = f2;
    spair.y = s2;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + (kbase + 2) * kGemmM + r) = spair;
  }
  // Zero-fill the padded K columns 27..31.
  for (int idx = tid; idx < (kGemmK - kKActual) * kRowPairs; idx += kThreads) {
    const int zp = idx / kRowPairs;
    const int r = (idx - zp * kRowPairs) * 2;
    const int k = kKActual + zp;
    __nv_bfloat162 spair;
    spair.x = bf16_zero;
    spair.y = bf16_zero;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + k * kGemmM + r) = spair;
  }
  // Load B directly in the native [out_channel][k] order as col-major KxN.
  for (int idx = tid; idx < kGemmN * kGemmK; idx += kThreads) {
    const int n = idx / kGemmK;
    const int k = idx - n * kGemmK;
    __nv_bfloat16 value = bf16_zero;
    if (k < kKActual) {
      const int ci = k / (kKernel * kKernel);
      const int rem = k - ci * (kKernel * kKernel);
      const int kh = rem / kKernel;
      const int kw = rem - kh * kKernel;
      value = W[((int64_t)n * kInChannels + ci) * kKernel * kKernel +
                kh * kKernel + kw];
    }
    smem_b[idx] = value;
  }
  __syncthreads();
  const int warp = tid >> 5;
  const int warp_m = (warp >> 1) * kWarpTile;
  const int warp_n = (warp & 1) * kWarpTile;
  // Register blocking: each warp owns one 16-wide N strip and accumulates
  // kWarpMTiles 16x16 M-tiles in registers, reusing the same B fragment
  // across all of them. This doubles arithmetic intensity per B fragment
  // load compared to the previous two-tile version and halves the number
  // of CTAs (and thus B loads) per output pixel.
  constexpr int kMWarpStride = (kWarps / 2) * kWarpTile;
  wmma::fragment<wmma::accumulator, kWarpTile, kWarpTile, kWarpTile, float>
      c_frag[kWarpMTiles];
#pragma unroll
  for (int i = 0; i < kWarpMTiles; ++i) {
    wmma::fill_fragment(c_frag[i], 0.0f);
  }
  // K tile is 32 (27 real + 5 zero-padded), so two 16x16x16 steps cover it.
  for (int k_step = 0; k_step < kGemmK; k_step += kWarpTile) {
    wmma::fragment<wmma::matrix_b, kWarpTile, kWarpTile, kWarpTile,
                   __nv_bfloat16, wmma::col_major> b_frag;
    // B is KxN col-major (ldm = kGemmK): one K sub-tile = kWarpTile rows.
    wmma::load_matrix_sync(b_frag, smem_b + warp_n * kGemmK + k_step, kGemmK);
#pragma unroll
    for (int i = 0; i < kWarpMTiles; ++i) {
      wmma::fragment<wmma::matrix_a, kWarpTile, kWarpTile, kWarpTile,
                     __nv_bfloat16, wmma::col_major> a_frag;
      // A is MxK col-major (ldm = kGemmM): one K sub-tile = kGemmM elements.
      wmma::load_matrix_sync(
          a_frag, smem_a + k_step * kGemmM + warp_m + i * kMWarpStride, kGemmM);
      wmma::mma_sync(c_frag[i], a_frag, b_frag, c_frag[i]);
    }
  }
  __syncthreads();
  // All warps are done reading A/B; C may now reuse that shared storage.
  // Each warp stages one 16x16 fp32 tile at a time in its private 1KB
  // slice and streams it straight to global memory as bf16, instead of
  // staging the whole 256x32 fp32 C tile. This shrinks the C staging
  // footprint from ~33KB to 8KB, lifting the smem-imposed occupancy cap.
  const int lane = tid & 31;
  float* warp_c = smem_c + warp * kSmemCWarpFloats;
#pragma unroll
  for (int i = 0; i < kWarpMTiles; ++i) {
    wmma::store_matrix_sync(warp_c, c_frag[i], kWarpTile, wmma::mem_col_major);
    __syncwarp();
    const int tile_m = warp_m + i * kMWarpStride;
    const bool tile_full =
        ((int64_t)m0 + tile_m + (kWarpTile - 1) < pixels_per_image);
    const bool aligned8 = ((y_c_stride & 3) == 0);
    if (tile_full && aligned8) {
      // Interior tile: write four bf16 outputs per lane with 8B stores.
      // For a fixed channel, warp_c is m-contiguous and global_m is too,
      // so four lanes cover one 32B channel segment instead of 16 scalar stores.
      #pragma unroll
      for (int nb = 0; nb < 2; ++nb) {
        const int n = nb * 8 + (lane >> 2);
        const int m_base = (lane & 3) * 4;
        const float4 q = *reinterpret_cast<const float4*>(
            warp_c + n * kWarpTile + m_base);
        __nv_bfloat162 p01, p23;
        p01.x = __float2bfloat16_rn(q.x);
        p01.y = __float2bfloat16_rn(q.y);
        p23.x = __float2bfloat16_rn(q.z);
        p23.y = __float2bfloat16_rn(q.w);
        uint2 packed;
        packed.x = *reinterpret_cast<unsigned*>(&p01);
        packed.y = *reinterpret_cast<unsigned*>(&p23);
        const int64_t global_m = (int64_t)m0 + tile_m + m_base;
        *reinterpret_cast<uint2*>(y_batch + (int64_t)(warp_n + n) * y_c_stride + global_m) = packed;
      }
    } else {
      #pragma unroll
      for (int e = 0; e < kSmemCWarpFloats / 32; ++e) {
        const int idx = e * 32 + lane;
        const int m = idx & (kWarpTile - 1);
        const int n = idx / kWarpTile;
        const int64_t global_m = (int64_t)m0 + tile_m + m;
        if (global_m < pixels_per_image) {
          y_batch[(int64_t)(warp_n + n) * y_c_stride + global_m] =
              __float2bfloat16_rn(warp_c[idx]);
        }
      }
    }
    }
    __syncwarp();
  }
}

