    const int rem_ci = idx - ci * (kKernel * kRowPairs);
    const int kh = rem_ci / kRowPairs;
    const int rp = rem_ci - kh * kRowPairs;
    const int r = rp * 2;
    const int kbase = (ci * kKernel + kh) * kKernel;
    __nv_bfloat16 f0 = bf16_zero, f1 = bf16_zero, f2 = bf16_zero;
    __nv_bfloat16 s0 = bf16_zero, s1 = bf16_zero, s2 = bf16_zero;
    const int64_t global_m = (int64_t)m0 + r;
    if (global_m < pixels_per_image) {
      const int out_h = (int)(global_m / width_out);
      const int out_w = (int)(global_m - (int64_t)out_h * width_out);
      const __nv_bfloat16* src0 = x_batch + (int64_t)ci * x_c_stride +
                                  (int64_t)(out_h + kh) * width_in + out_w;
      const bool has_second = (global_m + 1 < pixels_per_image);
      const bool same_row = has_second && (out_w + 1 < width_out);
      if (same_row) {
        __nv_bfloat16 i0, i1, i2, i3;
        if ((reinterpret_cast<uintptr_t>(src0) & 0x3) == 0) {
          const __nv_bfloat162 q0 =
              *reinterpret_cast<const __nv_bfloat162*>(src0);
          const __nv_bfloat162 q1 =
              *reinterpret_cast<const __nv_bfloat162*>(src0 + 2);
          i0 = q0.x;
          i1 = q0.y;
          i2 = q1.x;
          i3 = q1.y;
        } else {
          i0 = src0[0];
          i1 = src0[1];
          i2 = src0[2];
          i3 = src0[3];
        }
        f0 = i0;
        f1 = i1;
        f2 = i2;
        s0 = i1;
        s1 = i2;
        s2 = i3;
      } else {
        f0 = src0[0];
        f1 = src0[1];
        f2 = src0[2];
        if (has_second) {
          const __nv_bfloat16* srcw = x_batch + (int64_t)ci * x_c_stride +
                                      (int64_t)(out_h + 1 + kh) * width_in;
          s0 = srcw[0];
          s1 = srcw[1];
          s2 = srcw[2];
        }
      }
    }
    __nv_bfloat162 spair;
    spair.x = f0;
    spair.y = s0;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + (kbase + 0) * kGemmM + r) = spair;
    spair.x = f1;
    spair.y = s1;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + (kbase + 1) * kGemmM + r) = spair;
    spair.x = f2;
    spair.y = s2;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + (kbase + 2) * kGemmM + r) = spair;
  }
  // Zero-fill the padded K columns 27..31.
  for (int idx = tid; idx < (kGemmK - kKActual) * kRowPairs; idx += kThreads) {
    const int zp = idx / kRowPairs;
    const int r = (idx - zp * kRowPairs) * 2;
    const int k = kKActual + zp;
    __nv_bfloat162 spair;
    spair.x = bf16_zero;
    spair.y = bf16_zero;
    *reinterpret_cast<__nv_bfloat162*>(smem_a + k * kGemmM + r) = spair;
  }
  // Load B directly in the native [out_channel][k] order as col-major KxN.
  for (int idx = tid; idx < kGemmN * kGemmK; idx += kThreads) {
    const int n = idx / kGemmK;
    const int k = idx - n * kGemmK;
    __nv_bfloat16 value = bf16_zero;
    if (k < kKActual) {
      const int ci = k / (kKernel * kKernel);
      const int rem = k - ci * (kKernel * kKernel);
      const int kh = rem / kKernel;
      const int kw = rem - kh * kKernel;
      value = W[((int64_t)n * kInChannels + ci) * kKernel * kKernel +
                kh * kKernel + kw];
    }
    smem_b[idx] = value;
  }
  __syncthreads();
  const int warp = tid >> 5;
  const int warp_m = (warp >> 1) * kWarpTile;
  const int warp_n = (warp & 1) * kWarpTile;
  // Register blocking: each warp owns one 16-wide N strip and accumulates
  // kWarpMTiles 16x16 M-tiles in registers, reusing the same B fragment
  // across all of them. This doubles arithmetic intensity per B fragment
  // load compared to the previous two-tile version and halves the number
  // of CTAs (and thus B loads) per output pixel.
  constexpr int kMWarpStride = (kWarps / 2) * kWarpTile;
  wmma::fragment<wmma::accumulator, kWarpTile, kWarpTile, kWarpTile, float>
      c_frag[kWarpMTiles];
#pragma unroll
  for (int i = 0; i < kWarpMTiles; ++i) {
    wmma::fill_fragment(c_frag[i], 0.0f);
  }
  // K tile is 32 (27 real + 5 zero-padded), so two 16x16x16 steps cover it.
  for (int k_step = 0; k_step < kGemmK; k_step += kWarpTile) {
    wmma::fragment<wmma::matrix_b, kWarpTile, kWarpTile, kWarpTile,
                   __nv_bfloat16, wmma::col_major> b_frag;
    // B is KxN col-major (ldm = kGemmK): one K sub-tile = kWarpTile rows.
    wmma::load_matrix_sync(b_frag, smem_b + warp_n * kGemmK + k_step, kGemmK);
#pragma unroll
    for (int i = 0; i < kWarpMTiles; ++i) {
      wmma::fragment<wmma::matrix_a, kWarpTile, kWarpTile, kWarpTile,
                     __nv_bfloat16, wmma::col_major> a_frag;
      // A is MxK col-major (ldm = kGemmM): one K sub-tile = kGemmM elements.
      wmma::load_matrix_sync(
          a_frag, smem_a + k_step * kGemmM + warp_m + i * kMWarpStride, kGemmM);
      wmma::mma_sync(c_frag[i], a_frag, b_frag, c_frag[i]);
    }
  }
  __syncthreads();
  // All warps are done reading A/B; C may now reuse that shared storage.
  // Each warp stages one 16x16 fp32 tile at a time in its private 1KB
  // slice and streams it straight to global memory as bf16, instead of
  // staging the whole 256x32 fp32 C tile. This shrinks the C staging
  // footprint from ~33KB to 8KB, lifting the smem-imposed occupancy cap.
  const int lane = tid & 31;
  float* warp_c = smem_c + warp * kSmemCWarpFloats;
#pragma unroll
  for (int i = 0; i < kWarpMTiles; ++i) {
    wmma::store_matrix_sync(warp_c, c_frag[i], kWarpTile, wmma::mem_col_major);
    __syncwarp();
    const int tile_m = warp_m + i * kMWarpStride;
#pragma unroll
    for (int e = 0; e < kSmemCWarpFloats / 32; ++e) {
      const int idx = e * 32 + lane;
      const int m = idx & (kWarpTile - 1);
      const int n = idx / kWarpTile;
      const int64_t global_m = (int64_t)m0 + tile_m + m;
      if (global_m < pixels_per_image) {
        y_batch[(int64_t)(warp_n + n) * y_c_stride + global_m] =
            __float2bfloat16_rn(warp_c[idx]);
      }
    }
    __syncwarp();
  }
}

torch::Tensor conv2d_bf16_k3_cin3_forward(torch::Tensor x, torch::Tensor weight) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
  TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must have shape [C_out, C_in, KH, KW]");

  const int64_t batch = x.size(0);
  const int64_t in_channels = x.size(1);
  const int64_t height_in = x.size(2);
  const int64_t width_in = x.size(3);

  TORCH_CHECK(in_channels == kInChannels, "Only 3 input channels are supported");
  TORCH_CHECK(weight.size(0) == kOutChannels, "Only 32 output channels are supported");
  TORCH_CHECK(weight.size(1) == kInChannels, "weight.size(1) must be 3");
  TORCH_CHECK(weight.size(2) == kKernel && weight.size(3) == kKernel,
              "Only 3x3 kernels are supported");
  TORCH_CHECK(height_in >= kKernel && width_in >= kKernel,
              "Input spatial dimensions must be at least 3");

  const int64_t height_out = height_in - kKernel + 1;
  const int64_t width_out = width_in - kKernel + 1;

  auto x_c = x.contiguous();
  auto weight_c = weight.contiguous();
  auto y = torch::empty({batch, kOutChannels, height_out, width_out}, x.options());

  const int64_t x_batch_stride =
      (int64_t)kInChannels * height_in * width_in;
  const int64_t y_batch_stride =
      (int64_t)kOutChannels * height_out * width_out;

  const __nv_bfloat16* x_ptr =
      reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr());
  const __nv_bfloat16* w_ptr =
      reinterpret_cast<const __nv_bfloat16*>(weight_c.data_ptr());
  __nv_bfloat16* y_ptr =
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr());

  dim3 block(kThreads);
  const int64_t pixels_per_image = height_out * width_out;
  dim3 grid(
      (unsigned)((pixels_per_image + kGemmM - 1) / kGemmM),
      (unsigned)batch
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_bf16_k3_cin3_kernel<<<grid, block, 0, stream>>>(
      x_ptr,
      w_ptr,
      y_ptr,
      (int)height_in,
      (int)width_in,
      (int)height_out,
      (int)width_out,
      x_batch_stride,
      y_batch_stride
  );

  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "conv2d_bf16_k3_cin3_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
